allow={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 src=(root/v['file']).read_text(); tree=ast.parse(src); compile(src,v['file'],'exec')
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==v['config']
 assert executable(tree)==executable(parent_tree),v['name']
 assert hashlib.sha256(src.encode()).hexdigest() in v['note']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allow for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allow
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','exec','eval','__import__','compile'}
 a=cfg['auxiliary_tower_overrides']['cart'][0]; b=32
 depth=cfg['nonowner_tower_depth']; retained=cfg['nonowner_residual']=='retained'
 private=2*((403*a+1 if depth==1 else 434*a+97)+(2264 if retained else 0))
 dense=166147+private
 assert str(dense) in v['note']
 print(v['name'], 'dense=',dense,'sha256=',hashlib.sha256(src.encode()).hexdigest())
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert {a['knowledge_id'] for a in p['knowledge_assessments']} >= set(r['context']['latest_knowledge_usage']['retrieved_ids'])
assert len({a['knowledge_id'] for a in p['knowledge_assessments']})==len(p['knowledge_assessments'])
for a in p['knowledge_assessments']:
 assert set(a)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
 assert a['decision'] in {'used','considered','rejected','unresolved'}
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
print('PASS: complete study schema, references, variant structure, syntax, literal configs, source/import boundaries, exact inherited executable AST, analytic counts, preserved baseline hash and knowledge coverage.')
